/*
 * The sounds that are recordings, not synthesised (no maths ever made a tea glass or a newsroom sound right), as
 * 16-bit mono PCM at 24 kHz (the hosts' voices' rate), base64; sfx.ts decodes them. Each is a few seconds cut,
 * faded and levelled with ffmpeg from a free sound Arda found on Pixabay (Pixabay Content License: free to use in an
 * app, no credit needed; credited anyway). To change one, cut the new file the same way and replace its string.
 * Each is one long string on one line: split into hundreds of `+` pieces, it overflowed the bundler's stack.
 */
export const RECORDED_RATE = 24000;

export const RECORDINGS = {
  /** "Stir four cups with a teaspoon" by sahidullah (Pixabay): 3 s from the middle of the stirring. */
  tea:
    '',
  /** "News report music" (freesound_community, Pixabay): its first 4 s, fading out, to open the news. */
  news:
    '',
};
